ALTER TABLE signals ADD COLUMN IsAnalyzable BOOLEAN;
UPDATE signals SET IsAnalyzable = CASE WHEN snrratio - 0.1 * ABS(noisefloordbm) > 0 THEN TRUE ELSE FALSE END;
CREATE OR REPLACE FUNCTION set_analyzable_flag() RETURNS TRIGGER AS $$
BEGIN
    NEW.IsAnalyzable := CASE WHEN NEW.snrratio - 0.1 * ABS(NEW.noisefloordbm) > 0 THEN TRUE ELSE FALSE END;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_set_analyzable_flag BEFORE INSERT OR UPDATE ON signals FOR EACH ROW EXECUTE FUNCTION set_analyzable_flag();

